sys_variable_value.value:
(function execute(inputs, outputs) {
    if (inputs.file_ids) {
        var inputData = inputs.file_ids;
        var filesArray = [];

        try {
            // 1. Try parsing it. 
            var parsed = JSON.parse(inputData);
            
            // 2. If it's a string (due to double-serialization), parse it AGAIN
            if (typeof parsed === 'string') {
                parsed = JSON.parse(parsed);
            }
            
            // 3. Ensure it's an array
            filesArray = Array.isArray(parsed) ? parsed : [parsed];
            
        } catch (e) {
            // 4. Fallback: If parsing fails, strip garbage and split by comma
            var clean = inputData.toString().replace(/[\[\]"\s]/g, '');
            filesArray = clean.split(',');
        }

        var helper = new x_1815796_itsmgr_0.AiBotHelper();
        // Pass the clean array to your helper
        var result = helper.deleteFilesFromBot(filesArray);
        
        outputs.success = result.success;
        outputs.error_message = result.error_message;
    }
})(inputs, outputs);

